#include <stdbool.h>
#include <stddef.h>

#define STACK_CAPACITY 4U

typedef struct {
    int items[STACK_CAPACITY];
    size_t count;
} Stack;

static bool push(Stack *stack, int value)
{
    if (stack == NULL || stack->count >= STACK_CAPACITY) return false;
    stack->items[stack->count] = value;
    ++stack->count;
    return true;
}

static bool pop(Stack *stack, int *out)
{
    if (stack == NULL || out == NULL || stack->count == 0U) return false;
    --stack->count;
    *out = stack->items[stack->count];
    return true;
}

int main(void)
{
    Stack stack = {{0}, 0U};
    int value = 0;
    if (!push(&stack, 10) || !push(&stack, 20)) return 1;
    if (!pop(&stack, &value) || value != 20) return 2;
    return 0;
}

#include <stdbool.h>
#include <stddef.h>

static bool peek(const int items[], size_t count, int *out)
{
    if (items == NULL || out == NULL || count == 0U) return false;
    *out = items[count - 1U];
    return true;
}

/* Contract: items points to at least count integers;
   count is the current number of stack elements. */
